mapper.select:
SELECT
*
FROM rum_event as r

    r.deleted = 0

        AND r.env = #{query.env}


        AND r.metric = #{query.metric}


        AND r.route_key = #{query.routeKey}


        AND r.release_ver = #{query.releaseVer}


        AND r.dim_key = #{query.dimKey}


        AND DATE(r.create_time) = #{query.day}


order by r.create_time

SELECT *
FROM rum_event as r

    r.deleted = 0
    AND r.metric = #{metric}
    AND r.create_time >= #{start}
    AND r.create_time < #{end}

SELECT
*
FROM rum_event as r

    r.deleted = 0

        AND r.env = #{query.env}


        AND r.route_key = #{query.routeKey}


        AND r.release_ver = #{query.releaseVer}


        AND DATE(r.create_time) = #{query.day}


order by r.create_time
